+	return len(p), nil
+}
+
+func TestSendFailureLogsRedactCredentials(t *testing.T) {
+	// Do not parallelize: this test temporarily replaces the global logger.
+	logs := make(logChannel, 8)
+	previous := slog.Default()
+	slog.SetDefault(slog.New(slog.NewJSONHandler(logs, nil)))
+	t.Cleanup(func() { slog.SetDefault(previous) })
+
+	srv := httptest.NewServer(http.HandlerFunc(func(http.ResponseWriter, *http.Request) {}))
+	srv.Close() // Real HTTP client connection failures, without an external API.
+	token := "123456789:" + strings.Repeat("FAKE_TELEGRAM_TOKEN_", 4)
+	const secretPath = "/services/TEAM/CHANNEL/UNIQUE_SECRET"
+	const chat = "private-chat-id"
+	const body = "private **notification** body"
+	n := New(token, chat, srv.URL+secretPath)
+	n.telegramBase = srv.URL
+	n.Send(body)
+
+	timer := time.NewTimer(5 * time.Second)
+	defer timer.Stop()
+	seen := make(map[string]bool)
+	for len(seen) < 2 {
+		select {
+		case line := <-logs:
+			var record map[string]any
+			if err := json.Unmarshal([]byte(line), &record); err != nil {
+				t.Fatal("invalid JSON log")
+			}
+			message, _ := record["msg"].(string)
+			if message != "telegram 전송 실패" && message != "slack 전송 실패" {
+				t.Errorf("unexpected log message: %q", message)
+				continue
+			}
+			seen[message] = true
+			for _, secret := range []string{token, n.SlackWebhook, secretPath, "UNIQUE_SECRET", chat, body} {
+				if strings.Contains(line, secret) {
+					t.Errorf("%s: sensitive value leaked", message)
+				}
+			}
+			if record["level"] != "WARN" {
+				t.Errorf("%s: expected warning", message)
+			}
+			if detail, ok := record["err"].(string); !ok || !strings.Contains(detail, "connect:") {
+				t.Errorf("%s: connection failure diagnostic missing", message)
+			}
+			for key := range record {
+				if key != "time" && key != "level" && key != "msg" && key != "err" {
+					t.Errorf("%s: unexpected log attribute %q", message, key)
+				}
+			}
+		case <-timer.C:
+			t.Fatalf("timed out waiting for both failure logs; observed %d", len(seen))
+		}
+	}
+}
